// Archivo generado con "npm run sync-queries". No editar a mano.
// Fuente: sql/dashboard/*.sql

export const QUERIES = {
  canales: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\ngasto AS (\n  SELECT \"date\" AS fecha,\n    CASE WHEN channel = 'Instagram Ads' THEN 'Meta Ads' ELSE channel END AS canal,\n    CASE WHEN currency_unit = 'EUR_CENTS' THEN spend_raw::numeric / 100 ELSE spend_raw::numeric END AS gasto_eur\n  FROM (SELECT DISTINCT \"date\", channel, spend_raw, currency_unit FROM public.marketing_spend) m\n  WHERE \"date\" BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n),\ningresos AS (\n  SELECT canal, COUNT(*) AS pedidos, SUM(total_amount_cents) / 100.0 AS ingresos_eur\n  FROM base\n  WHERE fecha >= DATE '2026-03-01'\n  GROUP BY canal\n),\ngasto_canal AS (\n  SELECT canal, SUM(gasto_eur) AS gasto_eur\n  FROM gasto\n  WHERE fecha >= DATE '2026-03-01'\n  GROUP BY canal\n)\nSELECT i.canal, i.pedidos,\n  ROUND(i.ingresos_eur, 2) AS ingresos_eur,\n  ROUND(g.gasto_eur, 2) AS gasto_eur,\n  ROUND(i.ingresos_eur / NULLIF(g.gasto_eur, 0), 1) AS iec,\n  ROUND(100.0 * g.gasto_eur / SUM(g.gasto_eur) OVER (), 1) AS pct_del_gasto,\n  ROUND(100.0 * i.ingresos_eur / SUM(i.ingresos_eur) OVER (), 1) AS pct_de_los_ingresos,\n  ROUND(i.ingresos_eur / i.pedidos, 2) AS ticket_medio_eur\nFROM ingresos i\nLEFT JOIN gasto_canal g ON g.canal = i.canal\nORDER BY iec DESC NULLS LAST",
  categorias: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\nlineas AS (\n  SELECT p.category, p.active, i.quantity, i.quantity * i.unit_price_cents AS importe_cents\n  FROM base b\n  JOIN public.order_items i ON i.order_id = b.id\n  JOIN public.products p ON p.id = CASE WHEN i.product_id = 24 THEN 2 ELSE i.product_id END\n)\nSELECT category,\n  ROUND(SUM(importe_cents) FILTER (WHERE active) / 100.0, 2) AS ingreso_lineas_eur,\n  ROUND(100.0 * SUM(importe_cents) FILTER (WHERE active) / SUM(SUM(importe_cents) FILTER (WHERE active)) OVER (), 1) AS pct,\n  SUM(quantity) FILTER (WHERE active) AS unidades,\n  ROUND(COALESCE(SUM(importe_cents) FILTER (WHERE NOT active), 0) / 100.0, 2) AS ingreso_retirados_eur\nFROM lineas\nGROUP BY category\nORDER BY ingreso_lineas_eur DESC NULLS LAST",
  codigos_promocionales: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\ncod AS (\n  SELECT DISTINCT x.order_id, pr.name AS codigo, pr.discount_pct\n  FROM public.order_promotions x\n  JOIN public.promotions pr ON pr.id = x.promotion_id\n)\nSELECT c.codigo, c.discount_pct,\n  COUNT(*) AS pedidos,\n  ROUND(SUM(b.total_amount_cents) / 100.0, 2) AS ingreso_eur,\n  ROUND(100.0 * SUM(b.total_amount_cents) / (SELECT SUM(total_amount_cents) FROM base), 1) AS pct_de_las_ventas\nFROM cod c\nJOIN base b ON b.id = c.order_id\nGROUP BY c.codigo, c.discount_pct\nUNION ALL\nSELECT 'Sin código', NULL, COUNT(*),\n  ROUND(SUM(total_amount_cents) / 100.0, 2),\n  ROUND(100.0 * SUM(total_amount_cents) / (SELECT SUM(total_amount_cents) FROM base), 1)\nFROM base\nWHERE id NOT IN (SELECT order_id FROM cod)\nORDER BY ingreso_eur DESC",
  evolucion_mensual: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n)\nSELECT to_char(fecha, 'YYYY-MM') AS mes,\n  COUNT(*) AS pedidos,\n  ROUND(SUM(total_amount_cents) / 100.0, 2) AS ventas_eur,\n  ROUND(AVG(total_amount_cents) / 100.0, 2) AS ticket_medio_eur\nFROM base\nGROUP BY 1\nORDER BY 1",
  kpis_cabecera: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n)\nSELECT COUNT(*) AS pedidos,\n  ROUND(SUM(total_amount_cents) / 100.0, 2) AS ventas_eur,\n  ROUND(AVG(total_amount_cents) / 100.0, 2) AS ticket_medio_eur,\n  COUNT(*) FILTER (WHERE canal IS NULL) AS sin_canal_mapeado,\n  (SELECT COUNT(*) FROM public.orders\n   WHERE status = 'delivered' AND NULLIF(deleted_at::text, '') IS NULL\n     AND created_at::date <= DATE '2026-06-30' AND subtotal_cents < 100) AS pedidos_menores_1_eur\nFROM base",
  kpis_clientes: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\ncli AS (\n  SELECT customer_id, COUNT(*) AS pedidos FROM base GROUP BY customer_id\n),\ndev AS (\n  SELECT COUNT(*) FILTER (WHERE status = 'refunded') AS reembolsados, COUNT(*) AS entregados_y_reembolsados\n  FROM public.orders\n  WHERE status IN ('delivered', 'refunded')\n    AND NULLIF(deleted_at::text, '') IS NULL\n    AND created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND subtotal_cents >= 100\n)\nSELECT (SELECT COUNT(*) FROM cli) AS clientes_activos,\n  (SELECT COUNT(*) FROM cli WHERE pedidos >= 2) AS clientes_recurrentes,\n  ROUND(100.0 * (SELECT COUNT(*) FROM cli WHERE pedidos >= 2) / (SELECT COUNT(*) FROM cli), 1) AS tasa_recompra_pct,\n  d.reembolsados, d.entregados_y_reembolsados,\n  ROUND(100.0 * d.reembolsados / d.entregados_y_reembolsados, 2) AS tasa_devolucion_pct\nFROM dev d",
  paises: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n)\nSELECT country, COUNT(*) AS pedidos, COUNT(DISTINCT customer_id) AS clientes,\n  ROUND(SUM(total_amount_cents) / 100.0, 2) AS ventas_eur,\n  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS pct_pedidos,\n  ROUND(100.0 * SUM(total_amount_cents) / SUM(SUM(total_amount_cents)) OVER (), 1) AS pct_ventas,\n  ROUND(AVG(total_amount_cents) / 100.0, 2) AS ticket_medio_eur,\n  ROUND(AVG(subtotal_cents) / 100.0, 2) AS subtotal_medio_eur,\n  ROUND(1.0 * COUNT(*) / COUNT(DISTINCT customer_id), 1) AS pedidos_por_cliente\nFROM base\nGROUP BY country\nORDER BY ventas_eur DESC",
  pedidos_pendientes: "SELECT to_char(created_at::date, 'YYYY-MM') AS mes, status, COUNT(*) AS pedidos\nFROM public.orders\nWHERE NULLIF(deleted_at::text, '') IS NULL\n  AND created_at::date <= DATE '2026-06-30'\n  AND status = 'pending'\nGROUP BY 1, 2\nORDER BY 1",
  productos: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\nlineas AS (\n  SELECT CASE WHEN i.product_id = 24 THEN 2 ELSE i.product_id END AS pid,\n    i.quantity, i.quantity * i.unit_price_cents AS importe_cents\n  FROM base b\n  JOIN public.order_items i ON i.order_id = b.id\n),\nventas AS (\n  SELECT pid, SUM(quantity) AS unidades, SUM(importe_cents) AS importe_cents\n  FROM lineas\n  GROUP BY pid\n),\nresenas AS (\n  SELECT CASE WHEN product_id = 24 THEN 2 ELSE product_id END AS pid, customer_id, rating,\n    created_at::date AS fecha, id\n  FROM public.product_reviews\n  WHERE created_at::date <= DATE '2026-06-30'\n),\nultima AS (\n  SELECT DISTINCT ON (customer_id, pid) pid, rating\n  FROM resenas\n  ORDER BY customer_id, pid, fecha DESC, id DESC\n),\nvaloracion AS (\n  SELECT pid, COUNT(*) AS n, ROUND(AVG(rating), 2) AS media\n  FROM ultima\n  GROUP BY pid\n)\nSELECT p.id AS product_id, p.name, p.category, v.unidades,\n  ROUND(v.importe_cents / 100.0, 2) AS ingreso_lineas_eur,\n  r.media AS valoracion_media, r.n AS resenas\nFROM public.products p\nJOIN ventas v ON v.pid = p.id\nLEFT JOIN valoracion r ON r.pid = p.id\nWHERE p.active\nORDER BY ingreso_lineas_eur DESC",
  reparto_h2: "WITH base AS (\n  SELECT o.id, o.customer_id, o.country, o.created_at::date AS fecha,\n    CASE LOWER(TRIM(o.channel))\n      WHEN 'meta ads' THEN 'Meta Ads' WHEN 'instagram ads' THEN 'Meta Ads'\n      WHEN 'email' THEN 'Email' WHEN 'newsletter' THEN 'Email'\n      WHEN 'google ads' THEN 'Google Ads' WHEN 'tiktok ads' THEN 'TikTok Ads'\n      WHEN 'organic' THEN 'Organic' WHEN 'direct' THEN 'Direct'\n    END AS canal,\n    o.subtotal_cents, o.shipping_cents, o.total_amount_cents\n  FROM public.orders o\n  WHERE o.status = 'delivered'\n    AND NULLIF(o.deleted_at::text, '') IS NULL\n    AND o.created_at::date BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n    AND o.subtotal_cents >= 100\n),\ngasto AS (\n  SELECT \"date\" AS fecha,\n    CASE WHEN channel = 'Instagram Ads' THEN 'Meta Ads' ELSE channel END AS canal,\n    CASE WHEN currency_unit = 'EUR_CENTS' THEN spend_raw::numeric / 100 ELSE spend_raw::numeric END AS gasto_eur\n  FROM (SELECT DISTINCT \"date\", channel, spend_raw, currency_unit FROM public.marketing_spend) m\n  WHERE \"date\" BETWEEN DATE '2026-01-01' AND DATE '2026-06-30'\n),\ningresos AS (\n  SELECT canal, SUM(total_amount_cents) / 100.0 AS ingresos_eur\n  FROM base\n  WHERE fecha >= DATE '2026-03-01'\n  GROUP BY canal\n),\ngasto_canal AS (\n  SELECT canal, SUM(gasto_eur) AS gasto_eur\n  FROM gasto\n  WHERE fecha >= DATE '2026-03-01'\n  GROUP BY canal\n),\niec AS (\n  SELECT i.canal, g.gasto_eur, i.ingresos_eur / g.gasto_eur AS iec\n  FROM ingresos i\n  JOIN gasto_canal g ON g.canal = i.canal\n)\nSELECT ROUND(m.gasto_eur / 4, 2) AS meta_gasto_mensual_eur,\n  ROUND(m.gasto_eur / 4 * 6, 2) AS meta_gasto_h2_eur,\n  ROUND(m.gasto_eur / 4 * 6 * 0.25, 2) AS traslado_eur,\n  ROUND(e.gasto_eur / 4 * 6, 2) AS email_gasto_h2_eur,\n  ROUND((SELECT SUM(gasto_eur) FROM gasto_canal) / 4 * 6, 2) AS gasto_total_h2_eur,\n  ROUND(m.iec, 2) AS iec_meta,\n  ROUND(e.iec, 2) AS iec_email,\n  ROUND(100.0 * m.iec / e.iec, 1) AS iec_minimo_email_pct_del_medio,\n  ROUND(m.gasto_eur / 4 * 6 * 0.25 * m.iec, 2) AS ingresos_que_deja_de_atribuir_meta_eur,\n  ROUND(m.gasto_eur / 4 * 6 * 0.25 * e.iec, 2) AS ingresos_si_email_mantiene_su_iec_eur\nFROM iec m, iec e\nWHERE m.canal = 'Meta Ads' AND e.canal = 'Email'",
} as const;
